-- Conversation module test: replays the chat events the bridge produces for
-- recorded Claude and Codex turns (agent/tests/fixtures, generated by the
-- bridge's npm test). Runs in Aseprite batch mode:
--   aseprite -b --script-param ext=<agent/extension> --script-param fixtures=<agent/tests/fixtures> \
--     --script agent/tests/conversation_test.lua

local Conversation = dofile(app.fs.joinPath(app.params.ext, "conversation.lua"))

local failures = 0
local function check(name, cond, detail)
  if cond then print("PASS " .. name)
  else failures = failures + 1; print("FAIL " .. name .. (detail and (": " .. tostring(detail)) or "")) end
end

local function readEvents(name)
  local f = assert(io.open(app.fs.joinPath(app.params.fixtures, name)))
  local events = json.decode(f:read("a"))
  f:close()
  return events
end

-- A clock the test advances by hand.
local t = 1000
local clock = function() return t end

for _, provider in ipairs{ "claude", "codex" } do
  local c = Conversation.new{ clock = clock }
  c:send("Draw a red pixel", provider)
  check(provider .. ": busy after send", c:isBusy())
  local e = c:entries()
  check(provider .. ": user + header", e[1].kind == "user" and e[2].kind == "header")

  local ended = false
  for _, ev in ipairs(readEvents("chat-events-" .. provider .. ".json")) do
    t = t + 2
    local r = c:apply(ev)
    if r.turnEnded then ended = true end
  end
  check(provider .. ": turn ended on done", ended and not c:isBusy())
  check(provider .. ": conversation id kept", c:conversationId(provider) ~= nil)

  local tools, ok, texts = 0, 0, 0
  for _, x in ipairs(c:entries()) do
    if x.kind == "tool" then
      tools = tools + 1
      if x.status == "ok" then ok = ok + 1 end
    elseif x.kind == "text" then texts = texts + 1 end
  end
  check(provider .. ": every tool resolved", tools > 0 and ok == tools, ok .. "/" .. tools)
  check(provider .. ": reply recorded", texts > 0)
  local last = c:entries()[#c:entries()]
  check(provider .. ": worked for N s", last.kind == "worked" and last.secs > 0, last.kind)
end

-- Timing, errors and reset, with a fresh conversation.
do
  local c = Conversation.new{ clock = clock }
  t = 0
  c:send("hi", "claude")
  t = 3
  c:apply{ type = "thinking", text = "plan" }
  local thought = c:entries()[3]
  check("thought timed from the previous step", thought.kind == "thought" and thought.secs == 3, thought.secs)
  check("status events don't add entries", c:apply{ type = "status", text = "working" }.status == "working" and #c:entries() == 3)
  c:apply{ type = "tool_result", id = "unknown", ok = true }
  check("unknown tool result is ignored", #c:entries() == 3)
  t = 10
  local r = c:apply{ type = "error", text = "quota" }
  local n = #c:entries()
  check("error ends the turn", r.turnEnded and not c:isBusy() and c:entries()[n].kind == "worked" and c:entries()[n - 1].kind == "error")

  c:send("again", "codex")
  c:fail("bridge down")
  check("fail ends the turn", not c:isBusy() and c:entries()[#c:entries()].kind == "worked")

  c:apply{ type = "session", provider = "codex", sessionId = "th1" }
  c:reset()
  check("reset clears entries and ids", #c:entries() == 0 and c:conversationId("codex") == nil)
end

-- The turn's last check becomes a badge on "Worked for" (#29).
do
  local c = Conversation.new{ clock = clock }
  c:send("draw", "claude")
  c:apply{ type = "tool", id = "c1", tool = "Check pixel art", name = "check", kind = "read" }
  c:apply{ type = "tool_result", id = "c1", name = "check", ok = true, detail = "Check: 0 errors, 2 warnings (1 layers, 1 frames)" }
  c:apply{ type = "done" }
  local w = c:entries()[#c:entries()]
  check("check badge recorded", w.kind == "worked" and w.check and w.check.errors == 0 and w.check.warnings == 2)
  c:send("again", "claude")
  c:apply{ type = "done" }
  check("no check, no badge", c:entries()[#c:entries()].check == nil)
end

-- ACP: refined tool steps, plans and permission requests (#31).
do
  local c = Conversation.new{ clock = clock }
  c:send("draw", "claude")
  c:apply{ type = "tool", id = "t1", tool = "Run Lua", name = "execute_lua", kind = "edit" }
  c:apply{ type = "tool", id = "t1", tool = "Run Lua: add layer", name = "execute_lua", kind = "edit", detail = "code" }
  local tools = 0
  for _, e in ipairs(c:entries()) do if e.kind == "tool" then tools = tools + 1 end end
  local t = c:entries()[#c:entries()]
  check("same tool id refines the step", tools == 1 and t.text == "Run Lua: add layer" and t.detail == "code")

  c:apply{ type = "plan", entries = { { content = "Add layer", status = "in_progress" }, { content = "Draw", status = "pending" } } }
  c:apply{ type = "plan", entries = { { content = "Add layer", status = "completed" }, { content = "Draw", status = "in_progress" } } }
  local plans, plan = 0, nil
  for _, e in ipairs(c:entries()) do if e.kind == "plan" then plans = plans + 1; plan = e end end
  check("one plan per turn, updated in place", plans == 1 and plan.items[1].status == "completed" and #plan.items == 2)

  local r = c:apply{ type = "permission", requestId = "p1", text = "Run ls", options = { { optionId = "allow", name = "Allow" } } }
  check("permission is handed to the panel", r.permission and r.permission.requestId == "p1" and not r.turnEnded)
  c:recordPermission("Run ls", "Allow")
  check("answer recorded", c:entries()[#c:entries()].text == "Permission for Run ls: Allow")
  c:apply{ type = "done" }

  c:send("again", "claude")
  c:apply{ type = "plan", entries = { { content = "New", status = "pending" } } }
  plans = 0
  for _, e in ipairs(c:entries()) do if e.kind == "plan" then plans = plans + 1 end end
  check("next turn gets its own plan", plans == 2)
end

-- Modes (#24): the header shows Ask/Plan; a finished Plan turn offers Apply plan.
do
  local c = Conversation.new{ clock = clock }
  c:send("why", "claude", "ask")
  check("ask header", c:entries()[#c:entries()].text == "Claude · Ask")
  c:apply{ type = "done" }
  check("ask turn has no apply", not c:entries()[#c:entries()].applyPlan)
  c:send("plan it", "codex", "plan")
  check("plan header", c:entries()[#c:entries()].text == "Codex · Plan")
  c:apply{ type = "text", text = "1. Add layer" }
  c:apply{ type = "done" }
  check("finished plan offers apply", c:entries()[#c:entries()].applyPlan == true)
  c:send("plan again", "codex", "plan")
  c:apply{ type = "done", text = "Stopped." }
  local w = c:entries()[#c:entries() - 1]
  check("stopped plan has no apply", w.kind == "worked" and not w.applyPlan)
  c:send("go", "claude", "agent")
  check("agent header unlabeled", c:entries()[#c:entries()].text == "Claude")
end

-- Mentions and links (#20)
do
  local m = { Body = "aseprite://layer/L2", walk = "aseprite://tag/walk" }
  check("expand mentions", Conversation.expandMentions("outline @[Body] on @[walk]", m)
    == "outline Body (aseprite://layer/L2) on walk (aseprite://tag/walk)")
  check("unknown token stays", Conversation.expandMentions("hi @[Nope]", m) == "hi @[Nope]")

  local display, links = Conversation.parseLinks("Outlined [Body](aseprite://layer/L2) on [walk](aseprite://tag/walk). See [docs](https://x.y).")
  check("links -> display text", display == "Outlined Body on walk. See [docs](https://x.y).", display)
  check("link spans", #links == 2 and links[1].uri == "aseprite://layer/L2"
    and display:sub(links[1].from, links[1].to) == "Body" and display:sub(links[2].from, links[2].to) == "walk")
  local plain, none = Conversation.parseLinks("no links here")
  check("no links", plain == "no links here" and #none == 0)
end

print(failures == 0 and "ALL PASSED" or (failures .. " FAILED"))
